insert into public.pages (title, slug, kind, visibility, content) values
  ($taro$Data modeling$taro$, $taro$data-modeling$taro$, $taro$wiki$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data modeling is how we decide what our data means and how its pieces fit together — before and while we build the systems that store it. taro treats every model as part of one connected graph, so a table, the concept that defines its terms, and the decision that shaped it all point at each other."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The building blocks"}]},{"type":"paragraph","content":[{"type":"text","text":"Most modeling questions come back to a small set of fundamentals. Learn these and you can model almost anything."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"What data modeling is"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Why data modeling matters"}},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"The forms of data"}},{"type":"text","text":" — not everything is a table."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Attributes"}},{"type":"text","text":", and "},{"type":"wikilink","attrs":{"title":"Relationships"}},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Counting & aggregation"}},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Time in data modeling"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Modeling theory"}},{"type":"text","text":" — dimensional, one-big-table, and normalization trade-offs."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Putting it to work"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Perspectives on a model"}},{"type":"text","text":" — the same thing modeled for different consumers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Seeing the business"}},{"type":"text","text":" — processes, domains, and shared language."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Data modeling as continuous practice"}},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Then put it to work in an analytics stack: "},{"type":"wikilink","attrs":{"title":"Analytics engineering practice"}},{"type":"text","text":" covers materialization, observation, orchestration, testing, and ML/AI integration."}]}]}$taro$::jsonb),
  ($taro$What data modeling is$taro$, $taro$what-data-modeling-is$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A data model organizes and standardizes data into a precise, structured representation — one that guides both human and machine behavior, informs decisions, and enables action. It is not the database, not a single methodology, and never quite finished."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Model for humans and machines"}]},{"type":"paragraph","content":[{"type":"text","text":"Models have always served machines; today they also serve search and AI agents that read definitions to answer questions. Explicit meaning is what lets a person, a query, and an agent work from the same understanding — see "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What it is not"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not perfect — a model is a useful approximation of a slice of reality, not a replica."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not just physical storage — structure, relationships, and meaning come first; the table layout follows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not a single approach — normalized, dimensional, document, graph, and feature models are tools, not rival faiths. See "},{"type":"wikilink","attrs":{"title":"Modeling theory"}},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not one-and-done — see "},{"type":"wikilink","attrs":{"title":"Data modeling as continuous practice"}},{"type":"text","text":"."}]}]}]}]}$taro$::jsonb),
  ($taro$Why data modeling matters$taro$, $taro$why-data-modeling-matters$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The question is never whether you have a data model — the lack of one is still a model, just a poor one. The question is whether it is coherent. Most so-called data problems are really disagreements about meaning: two teams, two definitions of “customer,” contradictory dashboards."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Coherence is the payoff"}]},{"type":"paragraph","content":[{"type":"text","text":"A good model aligns data with how the business actually works — its vocabulary, rules, and workflows — so people and machines share one understanding. That shared definition is what makes the numbers trustworthy. See "},{"type":"wikilink","attrs":{"title":"Seeing the business"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"There is no free lunch"}]},{"type":"paragraph","content":[{"type":"text","text":"Every shortcut is a loan. Skipping the modeling work trades a little speed now for technical, data, and organizational debt later — fragile pipelines, conflicting metrics, and eroded trust that compound. Modeling is what lets you move faster safely, not slower."}]}]}$taro$::jsonb),
  ($taro$The forms of data$taro$, $taro$forms-of-data$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Not everything is a table. A data modeler works across several forms, and each demands its own approach. The fundamentals — "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Attributes"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Relationships"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Time in data modeling"}},{"type":"text","text":", and "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" — apply to all of them."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Structured — rows and columns with enforced types; the home of relational and dimensional models."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Semi-structured — JSON, events, and nested documents; flexible, but easy to model badly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unstructured — text, images, audio, video; you impose structure through metadata and derived features."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ML/AI artifacts — features, embeddings, model outputs, and agent traces; data in their own right."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Metadata — data about data: definitions, lineage, freshness, quality. Increasingly a first-class citizen."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A single event — an order, say — usually lives in several forms at once, tied together by a shared identifier. Keeping those representations consistent is the work. See "},{"type":"wikilink","attrs":{"title":"Perspectives on a model"}},{"type":"text","text":"."}]}]}$taro$::jsonb),
  ($taro$Entities, instances & identifiers$taro$, $taro$entities-and-identity$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An entity is a thing worth modeling — a customer, an order, a shipment. If you cannot name and identify it, you cannot model it. Each specific occurrence is an instance, and each instance needs an identifier to tell it apart from the rest."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Identifiers"}]},{"type":"paragraph","content":[{"type":"text","text":"Good identifiers are unique, stable, and simple. A natural key uses a real-world value (an email, an ISBN); a surrogate key is system-generated (a sequence or UUID). Natural keys are readable but tend to change; surrogate keys are stable and fast to join. Many systems keep a surrogate primary key and natural keys as indexed lookups."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Distinctions that matter"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strong vs. weak entities — a weak entity (an order line) cannot exist without its parent (an order)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Types and subtypes — a Product type with Physical and Digital subtypes that share a core and add their own."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An entity is a concept, not a table — the same customer is a row, a document, a feature vector, and a graph node. See "},{"type":"wikilink","attrs":{"title":"Perspectives on a model"}},{"type":"text","text":"."}]}]}]}]}$taro$::jsonb),
  ($taro$Attributes$taro$, $taro$attributes$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attributes are the properties that describe an entity — an order's date, total, and status. They are the vocabulary you use to describe your domain, so name them well."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Naming"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clarity — prefer order_date to date; avoid reserved words."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consistency — pick one convention (snake_case, say) and hold it everywhere."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Watch for"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nulls — decide what missing means; remember aggregates skip nulls while scalar math is poisoned by them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Attribute bloat — when an entity needs the word “and” to describe it, it has become a junk drawer; split it."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Different consumers reshape the same attribute: a descriptive property becomes a dimension for analytics and a feature for a model. See "},{"type":"wikilink","attrs":{"title":"Perspectives on a model"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":"."}]}]}$taro$::jsonb),
  ($taro$Relationships$taro$, $taro$relationships$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A relationship is a connection between entities — it is what turns isolated facts into a coherent picture. taro stores relationships as first-class edges in one graph, so any node can reference any other and every node shows its backlinks."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cardinality"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One-to-one — each side has exactly one of the other; used for security, performance, or optional extension."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One-to-many — the common case; a customer has many orders."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Many-to-many — resolved with a junction entity (order lines between orders and products)."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Explicit vs. inferred"}]},{"type":"paragraph","content":[{"type":"text","text":"Explicit relationships are declared and enforced — use them where correctness is load-bearing. Inferred relationships are computed (similarity, co-occurrence) — powerful for discovery, but probabilistic; never treat a 0.92 similarity as a foreign key. In semi-structured data, choose deliberately whether to embed or reference. See "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" for how joins change what a row means."}]}]}$taro$::jsonb),
  ($taro$Grain$taro$, $taro$grain$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grain answers one question: what does a single row represent? One row per order, per order line, per customer per day. It is the most consequential and most skipped decision in a model, and it underlies "},{"type":"wikilink","attrs":{"title":"Counting & aggregation"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Get it right early"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define the grain before you build, and write it down."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose the finest practical grain — you can always aggregate up, but you can never recover detail you threw away."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Watch for fan-out — joining tables at different grains silently multiplies rows and inflates counts."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"taro treats grain as a headline fact on every catalog node — a model or source states its grain in plain language, right next to its definition."}]}]}$taro$::jsonb),
  ($taro$Counting & aggregation$taro$, $taro$aggregation$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aggregation trades detail for a summary — a count, a sum, an average. It is also a stress test: a model that cannot be aggregated cleanly has a deeper problem with "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":", identity, or "},{"type":"wikilink","attrs":{"title":"Relationships"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Safe aggregation"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Aligned grain — only combine things at the same grain; mismatches double-count."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Disjoint groups — every row in exactly one bucket, or many-to-many overlaps inflate the total."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Additivity — some measures sum across every dimension, some only across some (a balance over time), some not at all (ratios, distinct counts)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Decomposability — averages are not associative; track sum and count separately and divide at the end."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Boundedness — a metric is meaningless without its time and dimension scope."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Aggregate aggressively for speed, but keep the path back to atomic data so any number can be traced and verified."}]}]}$taro$::jsonb),
  ($taro$Time in data modeling$taro$, $taro$time-in-data-modeling$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reality is not static, so models must handle change. The most common and most expensive bugs come from conflating different kinds of time."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Event time — when something actually happened."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ingestion time — when it reached your system."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Processing time — when your system acted on it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Valid time — the period a fact was true in the real world."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tracking history"}]},{"type":"paragraph","content":[{"type":"text","text":"Storing both valid time and the time the system recorded a fact (bitemporal modeling) lets you answer “what did we believe on this date?” — the idea behind slowly changing dimensions and point-in-time queries. For machine learning, a point-in-time (AS OF) join prevents leaking future data into training. Store timestamps in UTC with an explicit offset; never as strings. See "},{"type":"wikilink","attrs":{"title":"Counting & aggregation"}},{"type":"text","text":" for time-bounded metrics."}]}]}$taro$::jsonb),
  ($taro$Semantics & the semantic layer$taro$, $taro$semantics-and-the-semantic-layer$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Meaning is mostly shared meaning. A model's job is to capture what terms mean in a way people and machines can agree on. In taro, Concept pages are the semantic layer — a term is defined once and everything points at that definition."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"From vocabulary to structure"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A controlled vocabulary fixes one preferred term and maps synonyms to it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A taxonomy organizes terms into a hierarchy (Phones under Electronics)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An ontology adds the rules and relationships a machine can reason over."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Metadata — technical, business, and semantic — is the context that makes all of it usable."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This is what grounds an AI agent: with explicit definitions it follows your meaning of “customer” instead of guessing. See "},{"type":"wikilink","attrs":{"title":"ML / AI integration"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Why data modeling matters"}},{"type":"text","text":"."}]}]}$taro$::jsonb),
  ($taro$Perspectives on a model$taro$, $taro$perspectives-on-a-model$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The same business reality is modeled differently depending on who consumes it. None of these perspectives is the whole truth; a good modeler moves between them and keeps them coherent through shared identity and definitions."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Operational — normalized tables with constraints, optimized for consistent reads and writes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Analytical — facts and dimensions, denormalized for query speed and history."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Application — documents and events shaped around access patterns and velocity."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Machine learning — features and embeddings, where relationships are distances and probabilities."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Knowledge — nodes and typed edges that carry meaning a system can reason over."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"One customer is a row, a dimension, a document, a feature vector, and a graph node at once. The skill is recognizing which perspective a problem calls for. See "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Modeling theory"}},{"type":"text","text":"."}]}]}$taro$::jsonb),
  ($taro$Seeing the business$taro$, $taro$seeing-the-business$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You model the business, not just the systems. Before drawing tables, understand the processes that create data and the domains that give it meaning."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A business process is the horizontal flow of work — an event triggers steps that change a core object and produce an outcome."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A domain is a boundary of meaning — a place where words, rules, and ownership are consistent."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Shared language"}]},{"type":"paragraph","content":[{"type":"text","text":"The same word can mean different things across domains: an “order” is a signed deal to sales, a pick list to fulfillment, a refund reference to returns. Agree on a shared vocabulary, or model the translation between domains explicitly."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Context collapse"}]},{"type":"paragraph","content":[{"type":"text","text":"Flattening who, what, when, and why — dumping events into one table, collapsing timestamps into a single “date” — erases the context that made data meaningful. Preserving it with metadata is what keeps a model trustworthy. See "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Time in data modeling"}},{"type":"text","text":"."}]}]}$taro$::jsonb),
  ($taro$Data modeling as continuous practice$taro$, $taro$data-modeling-as-practice$taro$, $taro$concept$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A data model is a living reflection of the business, not a one-time project. As the business changes, the model has to change with it — treat it as an ongoing program."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Just-in-time modeling"}]},{"type":"paragraph","content":[{"type":"text","text":"Model to the question in front of you, ship a thin slice, and harden it — tests, docs, refactor — only once it becomes load-bearing. Moving slowly to move fast beats both big-design-up-front and throwing data in a pile."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Smells to watch for"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inconsistent or cryptic names; reserved words."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Redundant data duplicated across tables."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Repeated columns (PO_1, PO_2, PO_3) that should be rows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Overloaded tables stuffed with unrelated entities."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dogmatically applying one approach where it does not fit."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"See "},{"type":"wikilink","attrs":{"title":"Why data modeling matters"}},{"type":"text","text":" for the debt these create, and "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Counting & aggregation"}},{"type":"text","text":" for where they bite hardest."}]}]}$taro$::jsonb),
  ($taro$Analytics engineering practice$taro$, $taro$analytics-engineering-practice$taro$, $taro$wiki$taro$, $taro$viewer$taro$, $taro${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How the modeling fundamentals show up in an analytics-engineering stack — the strategies for building, observing, and orchestrating the analytics layer, and handing it off to ML and AI. (Formerly the standalone strategy library; now grounded in the fundamentals above.)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Materialization strategies"}},{"type":"text","text":" — view vs. table vs. incremental vs. ephemeral, and the cost/performance trade-offs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Observation strategies"}},{"type":"text","text":" — freshness, volume, distribution, anomalies, contracts, alerting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Orchestration strategies"}},{"type":"text","text":" — scheduling, dependency graphs, backfills, CI/CD for transformations."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" — test taxonomy, coverage, and contracts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"wikilink","attrs":{"title":"ML / AI integration"}},{"type":"text","text":" — feature/marts hand-off, embeddings and vector stores, LLM-assisted docs and semantic search."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"These build on the fundamentals in "},{"type":"wikilink","attrs":{"title":"Data modeling"}},{"type":"text","text":" — especially "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":", "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":", and "},{"type":"wikilink","attrs":{"title":"Time in data modeling"}},{"type":"text","text":"."}]}]}$taro$::jsonb)
on conflict (slug) do update set
  title = excluded.title,
  kind = excluded.kind,
  visibility = excluded.visibility,
  content = excluded.content,
  updated_at = now();

-- Re-home pages into one tree: fundamentals under "Data modeling", the
-- analytics-engineering practice concepts under their hub.
update public.pages c
  set parent_id = p.id
  from public.pages p
  where p.slug = $taro$data-modeling$taro$
    and c.slug = any(array[$taro$what-data-modeling-is$taro$, $taro$why-data-modeling-matters$taro$, $taro$forms-of-data$taro$, $taro$entities-and-identity$taro$, $taro$attributes$taro$, $taro$relationships$taro$, $taro$grain$taro$, $taro$aggregation$taro$, $taro$time-in-data-modeling$taro$, $taro$semantics-and-the-semantic-layer$taro$, $taro$perspectives-on-a-model$taro$, $taro$seeing-the-business$taro$, $taro$data-modeling-as-practice$taro$, $taro$analytics-engineering-practice$taro$, $taro$modeling-theory$taro$]);

update public.pages c
  set parent_id = p.id
  from public.pages p
  where p.slug = $taro$analytics-engineering-practice$taro$
    and c.slug = any(array[$taro$materialization-strategies$taro$, $taro$observation-strategies$taro$, $taro$orchestration-strategies$taro$, $taro$testing-and-data-quality$taro$, $taro$ml-ai-integration$taro$]);

-- Re-derive page→page links straight from the embedded wikilinks, so the
-- backlink graph matches the prose. Clear the seeded sources first for clean
-- re-runs, then resolve each [[Title]] to its page by (case-insensitive) title.
delete from public.links
  where source_type = 'page' and target_type = 'page'
    and source_id in (select id from public.pages where slug = any(array[$taro$data-modeling$taro$, $taro$what-data-modeling-is$taro$, $taro$why-data-modeling-matters$taro$, $taro$forms-of-data$taro$, $taro$entities-and-identity$taro$, $taro$attributes$taro$, $taro$relationships$taro$, $taro$grain$taro$, $taro$aggregation$taro$, $taro$time-in-data-modeling$taro$, $taro$semantics-and-the-semantic-layer$taro$, $taro$perspectives-on-a-model$taro$, $taro$seeing-the-business$taro$, $taro$data-modeling-as-practice$taro$, $taro$analytics-engineering-practice$taro$]));

insert into public.links (source_type, source_id, target_type, target_id)
select distinct 'page'::node_type, s.id, 'page'::node_type, t.id
  from public.pages s
  cross join lateral
    jsonb_path_query(s.content, '$.**?(@.type == "wikilink").attrs.title') as wl(val)
  join public.pages t on lower(t.title) = lower(wl.val #>> '{}')
  where s.slug = any(array[$taro$data-modeling$taro$, $taro$what-data-modeling-is$taro$, $taro$why-data-modeling-matters$taro$, $taro$forms-of-data$taro$, $taro$entities-and-identity$taro$, $taro$attributes$taro$, $taro$relationships$taro$, $taro$grain$taro$, $taro$aggregation$taro$, $taro$time-in-data-modeling$taro$, $taro$semantics-and-the-semantic-layer$taro$, $taro$perspectives-on-a-model$taro$, $taro$seeing-the-business$taro$, $taro$data-modeling-as-practice$taro$, $taro$analytics-engineering-practice$taro$])
    and t.id <> s.id
on conflict do nothing;
